#!/usr/bin/env bash
# Print the name of the tenant's coordinator ECR repository, for the build-coordinator-image
# workflow (both its build and join jobs call this, so they always agree on the target).
#
# The repository's name is generated by CloudFormation, so it is found one of two ways:
#   COORDINATOR_REPO  the exact repository name; it must exist in AWS_REGION.
#   BIFFIX_TENANT     the tenant; the repository is the one whose name starts with
#                     `biffix-<tenant>-data-coordinatorrepo` (the data stack `biffix-<tenant>-data`
#                     plus the CoordinatorRepo logical id, lowercased). The prefix is anchored, so
#                     tenant `acme` never matches `acme-dev`'s repository, and exactly one match is
#                     required: a retained repository from an earlier deploy of the same tenant
#                     fails here, loudly, rather than receiving the push. Set COORDINATOR_REPO then.
# COORDINATOR_REPO wins when both are set. AWS_REGION is required.
#
# docker/coordinator/build-and-push.sh resolves the same repository through the data stack's
# resources instead (CloudFormation access the CI role does not have).
set -euo pipefail

die() { printf 'resolve-repo: error: %s\n' "$*" >&2; exit 1; }

region="${AWS_REGION:-}"
[ -n "$region" ] || die "AWS_REGION is not set"

if [ -n "${COORDINATOR_REPO:-}" ]; then
  [[ "$COORDINATOR_REPO" =~ ^[a-z0-9][a-z0-9._/-]*$ ]] \
    || die "COORDINATOR_REPO is not a valid ECR repository name: '$COORDINATOR_REPO'"
  aws ecr describe-repositories --region "$region" --repository-names "$COORDINATOR_REPO" \
    --query 'repositories[0].repositoryName' --output text >/dev/null \
    || die "no ECR repository '$COORDINATOR_REPO' in $region (or describe-repositories failed)"
  printf '%s' "$COORDINATOR_REPO"
  exit 0
fi

tenant="${BIFFIX_TENANT:-}"
[ -n "$tenant" ] || die "set COORDINATOR_REPO (the exact repository name) or BIFFIX_TENANT"
# The tenant is pasted into a JMESPath query below, so admit only what a tenant name can be.
[[ "$tenant" =~ ^[A-Za-z0-9][A-Za-z0-9-]*$ ]] || die "BIFFIX_TENANT is not a valid tenant: '$tenant'"
prefix="$(printf 'biffix-%s-data-coordinatorrepo' "$tenant" | tr '[:upper:]' '[:lower:]')"

out="$(aws ecr describe-repositories --region "$region" \
  --query "repositories[?starts_with(repositoryName, '${prefix}')].repositoryName" --output text)" \
  || die "describe-repositories failed in $region"
[ "$out" = "None" ] && out=""
# --output text separates multiple values with tabs.
read -r -a repos <<<"$out"
if [ "${#repos[@]}" -ne 1 ]; then
  die "expected exactly 1 ECR repository named ${prefix}* in $region, found ${#repos[@]}: ${out:-<none>}; set COORDINATOR_REPO to the right one"
fi
printf '%s' "${repos[0]}"
